1	//! Epic status as a read-only rollup of its children.
2	//!
3	//! An EPIC's status is NOT a manually-set field — it is a projection of the
4	//! statuses of its children (the same child subtree `aida graph --tree` rolls
5	//! up). Manual epic status edits drift from reality in both directions: a
6	//! childless epic can read In Progress (false "active"), and an epic whose
7	//! children are shipping can read Draft (false "not started"). This module is
8	//! the single source of the derived status; every display surface (`aida list`
9	//! via the cache projection, `aida show`, `aida why`, `aida status`) routes
10	//! through it so the cache-backed and full-store paths agree, and the edit
11	//! guard in `aida-cli` rejects manual epic status sets so the field can't drift.
12	//!
13	//! The derivation reuses [`graph_walk::child_status_rollup`] — the SAME walk +
14	//! rollup the `--tree` render prints — so the derived status is always
15	//! consistent with the rollup numbers an operator sees.
16	//!
17	//! trace:BUG-626 | ai:claude
18	
19	use crate::graph_walk::{child_status_rollup, StatusRollup};
20	use crate::models::{RequirementStatus, RequirementType, RequirementsStore};
21	use uuid::Uuid;
22	
23	/// Derive an epic's effective status from the rollup of its children.
24	///
25	/// Precedence (evaluated top to bottom; `total` is the child count):
26	///
27	/// 1. **No children** (`total == 0`) -> `Draft` — nothing has started; the epic
28	///    still needs decomposition. (`aida why` already says "decompose — an epic
29	///    with no children yet"; this makes the status agree.)
30	/// 2. **All children Completed** -> `Completed`.
31	/// 3. **All children Done or Completed** (some on a branch, not all merged) ->
32	///    `Done`.
33	/// 4. **At least one child In Progress, OR a mix of done-and-not-done work** ->
34	///    `InProgress` — the epic is actively moving.
35	/// 5. **At least one child shelved (NeedsAttention) and none In Progress** ->
36	///    `NeedsAttention` — a child is blocked / needs a decision. (There is no
37	///    `Blocked` status variant; `NeedsAttention` is its closest analogue.)
38	/// 6. **Only remaining (Draft/Approved/Planned) children, none in progress** ->
39	///    `Draft` — queued but not started.
40	/// 7. **Only Rejected children** (every other bucket empty) -> `None`: we do not
41	///    auto-reject an epic. The caller keeps the epic's stored status so a human
42	///    can make that call (and `--force` recovery still works).
43	///
44	/// Returns `None` only in case (7); every other case yields a derived status.
45	// trace:BUG-626 | ai:claude
46	pub fn derive_epic_status_from_rollup(r: &StatusRollup) -> Option<RequirementStatus> {
47	    // (1) Childless epic — nothing started.
48	    if r.total == 0 {
49	        return Some(RequirementStatus::Draft);
50	    }
51	
52	    // (2) Every child Completed.
53	    if r.completed == r.total {
54	        return Some(RequirementStatus::Completed);
55	    }
56	
57	    // (3) Every child Done or Completed — work finished on branches, not all
58	    // merged yet.
59	    if r.done + r.completed == r.total {
60	        return Some(RequirementStatus::Done);
61	    }
62	
63	    // (4) Actively moving: a child is in progress, OR some work is already
64	    // done/completed while other children are not (a partially-shipped epic is
65	    // unambiguously "in progress").
66	    let any_finished = r.done + r.completed > 0;
67	    if r.in_progress > 0 || any_finished {
68	        return Some(RequirementStatus::InProgress);
69	    }
70	
71	    // From here: no in-progress and nothing finished — the epic hasn't started.
72	
73	    // (5) A child is shelved and nothing is moving — surface the stall.
74	    if r.shelved > 0 {
75	        return Some(RequirementStatus::NeedsAttention);
76	    }
77	
78	    // (6) Only queued work remains (Draft/Approved/Planned children).
79	    if r.remaining > 0 {
80	        return Some(RequirementStatus::Draft);
81	    }
82	
83	    // (7) Only Rejected children left (total > 0 but every non-rejected bucket is
84	    // empty). Don't auto-reject the epic; let the caller keep the stored status.
85	    None
86	}
