88	/// Derive an epic's effective status from the live store. Returns the rollup
89	/// status for an epic with the precedence above. Returns `None` when:
90	/// - `epic_id` doesn't resolve, or the resolved spec is not an Epic (callers
91	///   should only display the stored status for non-epics), or
92	/// - the epic's only children are Rejected (case 7 above — keep stored status).
93	// trace:BUG-626 | ai:claude
94	pub fn derive_epic_status(store: &RequirementsStore, epic_id: Uuid) -> Option<RequirementStatus> {
95	    let req = store.get_requirement_by_id(&epic_id)?;
96	    if req.req_type != RequirementType::Epic {
97	        return None;
98	    }
99	    let rollup = child_status_rollup(store, epic_id);
100	    derive_epic_status_from_rollup(&rollup)
101	}
