341	    /// Force a full cache rebuild, regardless of staleness. Used by the
342	    /// `aida cache rebuild` CLI command.
343	    pub fn rebuild_cache(&self) -> Result<usize> {
344	        let head = self.current_head_sha();
345	        let store = self.inner.load()?;
346	        let n = self.cache.rebuild_from_store(&store, &head)?;
347	        Ok(n)
348	    }
