350	    /// Re-stamp the cache HEAD-SHA after a write so the next stale-check
351	    /// passes. Called from write paths after `upsert_requirement` /
352	    /// `delete_requirement` succeed. Best-effort: if git HEAD can't be read
353	    /// (auto_commit disabled, not in a git repo) we leave the SHA alone and
354	    /// the cache will be considered fresh until a real commit happens.
355	    ///
356	    /// HAZARD this guards (TASK-712): a long-lived `CachedGitBackend` whose
357	    /// store branch was advanced by an EXTERNAL `git pull` (without reopening
358	    /// the backend) holds a cache that is stale — it is missing the pulled rows.
359	    /// A single-row write then upserts just the one written row and, if we
360	    /// blindly stamped the post-write HEAD, would mark the cache *fresh* while
361	    /// the pulled rows are still absent — they'd stay invisible until the next
362	    /// HEAD move. The single-row write paths do NOT call `ensure_cache_fresh`
363	    /// first (they are write-through, not read-then-write), so we cannot assume
364	    /// freshness here.
365	    ///
366	    /// Guard: only advance the recorded SHA when the cache was already current
367	    /// with the PRE-write HEAD (`pre_write_head`). If it was stale (recorded SHA
368	    /// differs, e.g. an external pull moved HEAD underneath us), we instead
369	    /// CLEAR the recorded SHA — exactly the "mark stale" signal used on a cache
370	    /// upsert failure — so the next read does a full rebuild from the store and
371	    /// picks up the pulled rows. This trades one extra rebuild for correctness.
372	    /// trace:TASK-712
373	    fn restamp_head(&self, pre_write_head: &str) {
374	        let head = self.current_head_sha();
375	        if head.is_empty() {
376	            return;
377	        }
378	        let recorded = self.cache.source_head_sha().ok().flatten();
379	        // Fresh iff the cache was recorded at the pre-write HEAD (the write's
380	        // own commit then advanced HEAD from pre_write_head to `head`). A
381	        // recorded SHA that is neither the pre-write HEAD nor absent means the
382	        // cache never ingested some externally-committed state → don't claim
383	        // freshness; force a rebuild.
384	        let was_current = match recorded.as_deref() {
385	            None => true,                   // first stamp / freshly rebuilt
386	            Some(s) => s == pre_write_head, // unchanged since we last freshened
387	        };
388	        if was_current {
389	            let _ = self.cache.set_source_head_sha(&head);
390	        } else {
391	            let _ = self.cache.set_source_head_sha("");
392	        }
393	    }
