395	    /// An EPIC's status is a read-only rollup of its children, so a child's
396	    /// status flip (or a newly-added/removed child) must refresh the PARENT
397	    /// epic's cached status. The single-row cache upsert can't do this on its
398	    /// own — it has no view of the epic's other children. Here we have the inner
399	    /// git store, so for each epic the written `req` is a child of (its
400	    /// reciprocal `Parent`/`Child` edges name the parent), we re-read the epic +
401	    /// its children from git, roll their statuses up, and re-stamp the epic's
402	    /// cache row. This keeps `aida list --status in-progress` truthful for epics
403	    /// without waiting for a full rebuild. Best-effort: a failed lookup leaves
404	    /// the epic to be corrected on the next full rebuild (the
405	    /// rebuildable-projection contract).
406	    ///
407	    /// Scope note: this rolls up the epic's DIRECT children only (cheap, no
408	    /// whole-store load on every write), whereas the full rebuild
409	    /// (`compute_epic_statuses` → `derive_epic_status` → transitive
410	    /// `child_status_rollup`) is the AUTHORITATIVE transitive value. The two
411	    /// agree for the overwhelmingly common case; an epic whose only finished
412	    /// work lives in a grandchild is reconciled on the next rebuild — same
413	    /// approximation contract as the cache's `in_degree` / `blocked` axes.
414	    // trace:BUG-626 | ai:claude
415	    fn refresh_parent_epic_status(&self, req: &Requirement) {
416	        use crate::graph_walk::status_rollup;
417	        use crate::models::{RelationshipType, RequirementType};
418	
419	        // A child stores the reciprocal edge to its parent (`Child --> parent`),
420	        // and some stores also carry `Parent --> parent`; union both so the
421	        // parent resolves whichever orientation was written. The epic itself, if
422	        // it is the thing written, is freshened by the cache upsert directly.
423	        let mut parent_ids: Vec<Uuid> = req
424	            .relationships
425	            .iter()
426	            .filter(|rel| {
427	                matches!(
428	                    rel.rel_type,
429	                    RelationshipType::Parent | RelationshipType::Child
430	                )
431	            })
432	            .map(|rel| rel.target_id)
433	            .collect();
434	        parent_ids.sort();
435	        parent_ids.dedup();
436	
437	        for parent_id in parent_ids {
438	            // Load the candidate parent; skip anything that isn't an epic.
439	            // BUG-634: targeted uuid→object resolve, not a full scan per edge.
440	            let Ok(Some(epic)) = self.get_requirement_targeted(&parent_id) else {
441	                continue;
442	            };
443	            if epic.req_type != RequirementType::Epic {
444	                continue;
445	            }
446	            // Resolve the epic's children from its OWN outbound Parent/Child
447	            // edges, load each, and roll the statuses up over a tiny store
448	            // (the epic + its children) — the same `status_rollup` the cache
449	            // rebuild path uses, so the two agree.
450	            let mut subset: Vec<Requirement> = vec![epic.clone()];
451	            let mut child_ids: Vec<Uuid> = Vec::new();
452	            for rel in &epic.relationships {
453	                if matches!(
454	                    rel.rel_type,
455	                    RelationshipType::Parent | RelationshipType::Child
456	                ) {
457	                    child_ids.push(rel.target_id);
458	                }
459	            }
460	            child_ids.sort();
461	            child_ids.dedup();
462	            for cid in &child_ids {
463	                // BUG-634: targeted resolve per child, not a full scan each.
464	                if let Ok(Some(child)) = self.get_requirement_targeted(cid) {
465	                    subset.push(child);
466	                }
467	            }
468	            let store = RequirementsStore {
469	                requirements: subset,
470	                ..Default::default()
471	            };
472	            let rollup = status_rollup(&store, &child_ids);
473	            let _ = self.cache.recompute_epic_status(&parent_id, &rollup);
474	        }
475	    }
