477	    /// Write-through batched update (BUG-425): apply many requirement updates
478	    /// in a SINGLE store commit (via `GitBackend::bulk_update`), then upsert
479	    /// each into the cache and re-stamp the HEAD-SHA once. Mirrors
480	    /// `update_requirement`'s write-through cache handling, batched. If any
481	    /// cache upsert fails the cache is marked stale so the next read rebuilds
482	    /// from the store. Returns the count whose YAML actually changed.
483	    /// trace:BUG-425 | ai:claude
484	    pub fn bulk_update(&self, requirements: &[Requirement], commit_subject: &str) -> Result<usize> {
485	        // Capture HEAD BEFORE the write so restamp_head can tell our own commit
486	        // apart from an external pull that moved HEAD underneath us. trace:TASK-712
487	        let pre_write_head = self.current_head_sha();
488	        let n = self.inner.bulk_update(requirements, commit_subject)?;
489	        let mut cache_ok = true;
490	        for req in requirements {
491	            if let Err(e) = self.cache.upsert_requirement(req) {
492	                eprintln!(
493	                    "warning: cache upsert failed during bulk_update, cache marked stale: {}",
494	                    e
495	                );
496	                cache_ok = false;
497	                break;
498	            }
499	        }
500	        if cache_ok {
501	            // BUG-626: refresh each touched child's parent epic rollup status.
502	            for req in requirements {
503	                self.refresh_parent_epic_status(req);
504	            }
505	            self.restamp_head(&pre_write_head);
506	        } else {
507	            let _ = self.cache.set_source_head_sha("");
508	        }
509	        Ok(n)
510	    }
511	}
