1	//! Git-canonical storage with a SQLite cache view.
2	//!
3	//! Per EPIC-1-001 / docs/plans/2026-05-02-git-canonical-storage.md:
4	//! the inner GitBackend is the writer-of-record; the Cache is a
5	//! rebuildable read projection. Writes go to git first, then update the
6	//! cache (write-through). Reads delegate to git for now — Phase 2 will
7	//! switch list/search reads to the cache.
8	//!
9	//! trace:EPIC-1-001 | ai:claude
10	
11	use anyhow::{Context, Result};
12	use std::path::{Path, PathBuf};
13	use uuid::Uuid;
14	
15	use super::cache::{ArchiveFilter, Cache, DeferFilter, ListFilter, RequirementSummary};
16	use super::git_backend::GitBackend;
17	use super::traits::{BackendType, DatabaseBackend, UpdateResult};
18	use crate::models::{QueueEntry, Requirement, RequirementsStore, User};
19	
20	pub struct CachedGitBackend {
21	    inner: GitBackend,
22	    cache: Cache,
23	}
24	
25	impl CachedGitBackend {
26	    /// Open an existing git store at `git_root` with a SQLite cache at
27	    /// `cache_path`. If the cache is missing or stale (HEAD-SHA mismatch),
28	    /// it is rebuilt before this constructor returns.
29	    pub fn open(git_root: &Path, cache_path: &Path) -> Result<Self> {
30	        let inner = GitBackend::new(git_root)?;
31	        Self::with_inner(inner, cache_path)
32	    }
33	
34	    /// Wrap an already-configured GitBackend (e.g., one that was built with
35	    /// `.with_dispenser(...)`). The cache is opened or created at
36	    /// `cache_path` and rebuilt if stale before this returns.
37	    pub fn with_inner(inner: GitBackend, cache_path: &Path) -> Result<Self> {
38	        let cache = Cache::open(cache_path)?;
39	        let backend = CachedGitBackend { inner, cache };
40	        // BUG-664: the constructor is on the hot path of every read command
41	        // (`aida status`, `aida list`). Use the read-tolerant freshness check so
42	        // a reader serves the last-good snapshot when another process is already
43	        // rebuilding the cache, instead of contending for the write lock through
44	        // the ~25s retry ladder. Writers re-check freshness strictly on their own
45	        // write paths, and the SHA-based stale detection is unchanged.
46	        backend.ensure_cache_fresh_for_read()?;
47	        Ok(backend)
48	    }
49	
50	    /// Default cache location for a project's git store at `git_root`:
51	    /// `<project_root>/.aida/cache.db`. We never put the cache *inside* the
52	    /// store directory — that would pollute the orphan branch's worktree —
53	    /// so the probe starts at `git_root.parent()` and walks up.
54	    pub fn default_cache_path(git_root: &Path) -> PathBuf {
55	        let mut probe = match git_root.parent() {
56	            Some(p) => p.to_path_buf(),
57	            None => return git_root.with_extension("cache.db"),
58	        };
59	        for _ in 0..6 {
60	            if probe.join(".aida").is_dir() {
61	                return probe.join(".aida").join("cache.db");
62	            }
63	            match probe.parent() {
64	                Some(p) => probe = p.to_path_buf(),
65	                None => break,
66	            }
67	        }
68	        // Fall back to a sibling file next to the store root so we still
69	        // never write inside it.
70	        git_root.with_extension("cache.db")
71	    }
72	
73	    pub fn cache(&self) -> &Cache {
74	        &self.cache
75	    }
76	
77	    pub fn inner(&self) -> &GitBackend {
78	        &self.inner
79	    }
80	
81	    /// Cache-backed spec-id collision scan for the `aida add` hot path
82	    /// (BUG-701). Brings the cache up to the store's current HEAD first — so a
83	    /// collision that a just-completed pre-allocation pull introduced is visible
84	    /// — then runs the indexed group-by. In the steady state (cache already
85	    /// fresh, the common case) this is a sub-millisecond query instead of the
86	    /// old O(n) full-store `GitBackend::load()` scan; on the rare divergent-pull
87	    /// it pays a cache refresh that also serves the subsequent reads. Returns
88	    /// `(spec_id, uuid, title)` for every claimant of a collided spec_id.
89	    // trace:BUG-701 | ai:claude
90	    pub fn spec_id_collisions(&self) -> Result<Vec<(String, Uuid, String)>> {
91	        self.ensure_cache_fresh()?;
92	        self.cache.spec_id_collisions()
93	    }
94	
95	    /// Read the current git HEAD on the store branch. Empty string if not in a
96	    /// git repo (e.g., test fixture); stale check then collapses to "always
97	    /// fresh" which is fine for non-git scenarios.
98	    fn current_head_sha(&self) -> String {
99	        crate::git_ops::head_sha(self.inner.path()).unwrap_or_default()
100	    }
101	
102	    /// Resolve a UUID to its `Requirement` WITHOUT the O(n) `find_by_uuid` scan
103	    /// over every object file. The cache holds the stable uuid→spec_id mapping,
104	    /// so we resolve the spec_id from the cache then read the ONE matching YAML
105	    /// object (the read is authoritative — the cache only tells us which file).
106	    /// On any cache miss, a spec_id/uuid mismatch (defends against a torn cache
107	    /// row), or an unreadable cache, we fall back to the inner full scan so
108	    /// correctness never depends on cache freshness. The uuid→spec_id mapping is
109	    /// invariant (spec_ids are stable and never reused), so even a stale cache
110	    /// row resolves to the right file.
111	    // trace:BUG-634 | ai:claude
