#[test]
fn rejected_plus_completed_rolls_up_completed() {
    // total=3, completed=2, rejected=1 — zero open children => Completed.
    assert_eq!(
        derive_epic_status_from_rollup(&rollup(3, 2, 0, 0, 0, 0, 1)),
        Some(RequirementStatus::Completed)
