#[test]
fn rejected_plus_done_rolls_up_done() {
    // total=3, completed=1, done=1, rejected=1.
    assert_eq!(
        derive_epic_status_from_rollup(&rollup(3, 1, 1, 0, 0, 0, 1)),
        Some(RequirementStatus::Done)
    );
